// Nearest first, over the HNSW index. Relaxed order can hand rows back slightly out of order, so they're sorted again
func (q *Queries) NearestProducts(ctx context.Context, arg NearestProductsParams) ([]NearestProductsRow, error) {
	rows, err := q.db.QueryContext(ctx, nearestProducts,
		arg.Query,
		arg.Model,
		pq.Array(arg.Locales),
		arg.ChannelID,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []NearestProductsRow{}
	for rows.Next() {
		var i NearestProductsRow
		if err := rows.Scan(&i.SourceID, &i.Locale, &i.Distance); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

