const pruneStaleModelEmbeddings = `-- name: PruneStaleModelEmbeddings :execrows
DELETE FROM embeddings e
USING (SELECT old.source, old.source_id, old.locale, old.model, old.chunk FROM embeddings old WHERE old.model <> $1 LIMIT $2) stale
WHERE e.source = stale.source AND e.source_id = stale.source_id AND e.locale = stale.locale AND e.model = stale.model AND e.chunk = stale.chunk
`

type PruneStaleModelEmbeddingsParams struct {
	Model string `json:"model"`
	Lim   int32  `json:"lim"`
}

func (q *Queries) PruneStaleModelEmbeddings(ctx context.Context, arg PruneStaleModelEmbeddingsParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, pruneStaleModelEmbeddings, arg.Model, arg.Lim)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const similarMatchValues = `-- name: SimilarMatchValues :many
WITH members AS (
    SELECT p.id AS product_id, p.id AS member_id FROM catalog_products p WHERE p.id = ANY($1::uuid[])
    UNION ALL
    SELECT c.parent_id, c.child_id FROM catalog_product_children c WHERE c.parent_id = ANY($1::uuid[])
)
SELECT m.product_id, a.id AS attribute_id, a.name AS attribute_name, a.is_public, ('v:' || pav.attribute_value_id::text)::text AS value, av.matches_any
FROM members m
JOIN catalog_product_attribute_values pav ON pav.product_id = m.member_id
JOIN catalog_attributes a ON a.id = pav.attribute_id AND a.similar_match
JOIN catalog_attribute_values av ON av.id = pav.attribute_value_id
UNION
SELECT m.product_id, a.id, a.name, a.is_public, ('s:' || lower(btrim(p.attributes ->> a.slug)))::text, FALSE
FROM members m
JOIN catalog_products p ON p.id = m.member_id
JOIN catalog_attributes a ON a.similar_match AND jsonb_typeof(p.attributes -> a.slug) IN ('string', 'number', 'boolean')
WHERE btrim(p.attributes ->> a.slug) <> ''
`

type SimilarMatchValuesRow struct {
	ProductID     uuid.UUID `json:"product_id"`
	AttributeID   uuid.UUID `json:"attribute_id"`
	AttributeName string    `json:"attribute_name"`
	IsPublic      bool      `json:"is_public"`
	Value         string    `json:"value"`
	MatchesAny    bool      `json:"matches_any"`
}

// Each product's values on the attributes marked to match, its variants' included - a chosen value by its id, a typed one
// by its lower-cased text, and whether the value stands for all the others
func (q *Queries) SimilarMatchValues(ctx context.Context, ids []uuid.UUID) ([]SimilarMatchValuesRow, error) {
	rows, err := q.db.QueryContext(ctx, similarMatchValues, pq.Array(ids))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SimilarMatchValuesRow{}
	for rows.Next() {
		var i SimilarMatchValuesRow
		if err := rows.Scan(
			&i.ProductID,
			&i.AttributeID,
			&i.AttributeName,
			&i.IsPublic,
			&i.Value,
			&i.MatchesAny,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const trimEmbeddings = `-- name: TrimEmbeddings :exec
DELETE FROM embeddings
WHERE source = $1 AND source_id = $2 AND model = $3
  AND (NOT (locale = ANY($4::text[])) OR chunk >= COALESCE(($5::smallint[])[array_position($4::text[], locale)], 0))
`

type TrimEmbeddingsParams struct {
	Source   string    `json:"source"`
	SourceID uuid.UUID `json:"source_id"`
	Model    string    `json:"model"`
	Locales  []string  `json:"locales"`
	Chunks   []int16   `json:"chunks"`
}

// Passages past the document's new end, and locales it no longer has
func (q *Queries) TrimEmbeddings(ctx context.Context, arg TrimEmbeddingsParams) error {
	_, err := q.db.ExecContext(ctx, trimEmbeddings,
		arg.Source,
		arg.SourceID,
		arg.Model,
		pq.Array(arg.Locales),
		pq.Array(arg.Chunks),
	)
	return err
}

const upsertEmbedding = `-- name: UpsertEmbedding :exec
INSERT INTO embeddings (source, source_id, locale, model, chunk, content, content_hash, embedding)
VALUES ($1, $2, $3, $4, $5, $6, $7,
    CAST($8::text AS vector))
ON CONFLICT (source, source_id, locale, model, chunk)
DO UPDATE SET content = EXCLUDED.content, content_hash = EXCLUDED.content_hash, embedding = EXCLUDED.embedding, updated_at = now()
`

type UpsertEmbeddingParams struct {
	Source      string    `json:"source"`
	SourceID    uuid.UUID `json:"source_id"`
	Locale      string    `json:"locale"`
	Model       string    `json:"model"`
	Chunk       int16     `json:"chunk"`
	Content     string    `json:"content"`
	ContentHash []byte    `json:"content_hash"`
	Embedding   string    `json:"embedding"`
}

func (q *Queries) UpsertEmbedding(ctx context.Context, arg UpsertEmbeddingParams) error {
	_, err := q.db.ExecContext(ctx, upsertEmbedding,
		arg.Source,
		arg.SourceID,
		arg.Locale,
		arg.Model,
		arg.Chunk,
		arg.Content,
		arg.ContentHash,
		arg.Embedding,
	)
	return err
}
